parameters.checklist:
[
  {
    "id": "plan-has-its-sections",
    "assert": "the plan has Today, Target, Steps and Invariants sections",
    "cmd": "for section in Today Target Steps Invariants; do grep -q \"^## $section\" ${notes_dir}/refactor.md || exit 1; done",
    "origin": "pe-profile:safe-refactor@1.0.0"
  },
  {
    "id": "three-invariants",
    "assert": "the plan lists at least three numbered invariants",
    "cmd": "test \"$(grep -cE '^INV[0-9]+:' ${notes_dir}/refactor.md)\" -ge 3",
    "origin": "pe-profile:safe-refactor@1.0.0"
  },
  {
    "id": "plan-is-grounded",
    "context": [
      "${notes_dir}/refactor.md"
    ],
    "judge": "Is this plan grounded in the actual code — does it name real files and functions, describe a concrete target shape and list invariants a test can check? FAIL if any section is generic enough to fit any codebase, if an invariant is not observable behaviour, or if a step is too large to review on its own.",
    "blocking": true,
    "origin": "pe-profile:safe-refactor@1.0.0"
  }
]

[
  {
    "id": "tests-added",
    "assert": "characterization tests were added or changed",
    "cmd": "git diff --name-only ${base_ref} -- ${test_path} | grep -q . || git ls-files --others --exclude-standard -- ${test_path} | grep -q .",
    "origin": "pe-profile:safe-refactor@1.0.0"
  },
  {
    "id": "source-untouched",
    "assert": "no source file changed while pinning",
    "cmd": "test -z \"$(git diff --name-only ${base_ref} -- ${src_path})\" && test -z \"$(git ls-files --others --exclude-standard -- ${src_path})\"",
    "origin": "pe-profile:safe-refactor@1.0.0"
  },
  {
    "id": "pins-pass-today",
    "assert": "the suite passes against today's code",
    "cmd": "${test_cmd}",
    "origin": "pe-profile:safe-refactor@1.0.0"
  },
  {
    "id": "every-invariant-pinned",
    "assert": "every invariant id from the plan appears in the tests",
    "cmd": "ids=$(grep -oE '^INV[0-9]+' ${notes_dir}/refactor.md) || exit 1; for id in $ids; do grep -rqw \"$id\" ${test_path} || { echo \"$id is not pinned\"; exit 1; }; done",
    "origin": "pe-profile:safe-refactor@1.0.0"
  }
]

[
  {
    "id": "source-changed",
    "assert": "the source paths were changed",
    "cmd": "git diff --name-only ${base_ref} -- ${src_path} | grep -q . || git ls-files --others --exclude-standard -- ${src_path} | grep -q .",
    "origin": "pe-profile:safe-refactor@1.0.0"
  },
  {
    "id": "suite-is-green",
    "assert": "the pinned tests and the rest of the suite pass",
    "cmd": "${test_cmd}",
    "origin": "pe-profile:safe-refactor@1.0.0"
  },
  {
    "id": "lint-is-clean",
    "assert": "the linter passes",
    "cmd": "${lint_cmd}",
    "origin": "pe-profile:safe-refactor@1.0.0"
  },
  {
    "id": "no-test-deleted",
    "assert": "no test file was deleted",
    "cmd": "! git diff --diff-filter=D --name-only ${base_ref} -- ${test_path} | grep -q .",
    "origin": "pe-profile:safe-refactor@1.0.0"
  },
  {
    "id": "behaviour-preserved",
    "context": [
      "${notes_dir}/refactor.md"
    ],
    "judge": "Does this change restructure the code toward the plan's target while keeping behaviour identical? FAIL if it edits, weakens or skips a pinned test, changes a public signature or output the invariants cover, or adds behaviour the plan does not mention.",
    "diff": true,
    "blocking": true,
    "origin": "pe-profile:safe-refactor@1.0.0"
  }
]

[
  {
    "id": "every-invariant-reviewed",
    "assert": "the review names every invariant id from the plan",
    "cmd": "ids=$(grep -oE '^INV[0-9]+' ${notes_dir}/refactor.md) || exit 1; for id in $ids; do grep -qw \"$id\" ${notes_dir}/refactor-review.md || { echo \"$id is not reviewed\"; exit 1; }; done",
    "origin": "pe-profile:safe-refactor@1.0.0"
  },
  {
    "id": "review-is-substantive",
    "assert": "the review carries at least 80 words",
    "cmd": "test \"$(wc -w < ${notes_dir}/refactor-review.md)\" -ge 80",
    "origin": "pe-profile:safe-refactor@1.0.0"
  },
  {
    "id": "review-is-honest",
    "context": [
      "${notes_dir}/refactor.md",
      "${notes_dir}/refactor-review.md"
    ],
    "judge": "Does this review check each invariant against a named test and account for every planned step? FAIL if it marks an invariant as holding without naming the test that shows it, skips a step from the plan, or claims something the code does not show.",
    "blocking": true,
    "origin": "pe-profile:safe-refactor@1.0.0"
  }
]
